<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import{get,post,type Row}from'../technicians/api';const props=defineProps<{canViewTeam:boolean;role:string}>();const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),attendance=ref<Row|null>(null),staff=ref<Row[]>([]),myLogs=ref<Row[]>([]),logs=ref<Row[]>([]),history=ref<Row[]>([]),dutyStatus=ref('AVAILABLE'),from=ref(new Date(Date.now()-30*864e5).toISOString().slice(0,10)),to=ref(new Date().toISOString().slice(0,10));const inputClass='min-h-11 rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-sm text-[var(--nx-text)]';const active=computed(()=>!!attendance.value?.time_in_at&&!attendance.value?.time_out_at),timedOut=computed(()=>!!attendance.value?.time_out_at);const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH'):'—';const label=(v:any)=>String(v||'OFFLINE').replaceAll('_',' ');const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>String(v).toUpperCase()==='AVAILABLE'?'success':String(v).toUpperCase()==='OFFLINE'?'neutral':['BUSY','ON_BREAK','TRAVELING','ON_SITE'].includes(String(v).toUpperCase())?'warning':'neutral';const duration=(m:any)=>`${Math.floor(Number(m||0)/60)}h ${Number(m||0)%60}m`;
async function load(show=false){loading.value=true;error.value='';try{const d=await get<any>('/api/v1/staff-attendance/today');attendance.value=d?.attendance||null;staff.value=d?.staff||[];myLogs.value=d?.my_logs||[];logs.value=d?.logs||[];if(attendance.value?.status&&attendance.value.status!=='OFFLINE')dutyStatus.value=attendance.value.status;if(props.canViewTeam)await loadHistory();if(show)notice.value='Attendance refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load attendance.';}finally{loading.value=false;}}async function loadHistory(){try{const d=await get<any>(`/api/v1/staff-attendance/history?from=${encodeURIComponent(from.value)}&to=${encodeURIComponent(to.value)}`);history.value=d?.items||[];}catch(e){error.value=e instanceof Error?e.message:'Unable to load attendance history.';}}async function command(url:string,payload:Row,message:string,question:string){if(!confirm(question))return;busy.value=true;try{await post(url,payload);notice.value=message;await load();}catch(e){error.value=e instanceof Error?e.message:'Attendance action failed.';}finally{busy.value=false;}}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Staff attendance" title="Time-In / Time-Out" description="Track duty state used by smart ticket assignment and work-order dispatch."><template #actions><NxButton variant="secondary" :disabled="loading||busy" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><div class="grid gap-4" :class="canViewTeam?'xl:grid-cols-[minmax(320px,1fr)_minmax(0,2fr)]':''"><NxCard title="My Attendance" description="Your current duty status today"><div class="space-y-4"><div class="rounded-md bg-[var(--nx-surface-muted)] p-4"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">Current Status</p><div class="mt-2"><NxBadge :tone="tone(attendance?.status)">{{label(attendance?.status)}}</NxBadge></div></div><div class="grid grid-cols-2 gap-3"><div class="rounded-md bg-[var(--nx-surface-muted)] p-3"><small class="text-[var(--nx-text-muted)]">Time In</small><b class="mt-1 block">{{fmt(attendance?.time_in_at)}}</b></div><div class="rounded-md bg-[var(--nx-surface-muted)] p-3"><small class="text-[var(--nx-text-muted)]">Time Out</small><b class="mt-1 block">{{fmt(attendance?.time_out_at)}}</b></div></div><div class="grid grid-cols-2 gap-2"><NxButton :disabled="busy||active||timedOut" @click="command('/api/v1/staff-attendance/time-in',{},'Time in recorded.','Time in now?')">Time In</NxButton><NxButton variant="danger" :disabled="busy||!active" @click="command('/api/v1/staff-attendance/time-out',{},'Time out recorded.','Time out now? This will mark you offline.')">Time Out</NxButton></div><label class="grid gap-2 text-sm font-semibold">Duty Status<select v-model="dutyStatus" :disabled="!active" :class="inputClass"><option>AVAILABLE</option><option>ON_BREAK</option><option>TRAVELING</option><option v-if="role!=='TECHNICIAN'">BUSY</option><option v-if="role!=='TECHNICIAN'">ON_SITE</option></select></label><NxButton class="w-full" variant="secondary" :disabled="busy||!active" @click="command('/api/v1/staff-attendance/status',{status:dutyStatus},'Duty status updated.','Update your duty status?')">Update Duty Status</NxButton></div></NxCard>
<NxCard v-if="canViewTeam" title="Today’s Staff" description="All active staff, including those currently offline"><NxTableShell min-width="760px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Staff</th><th class="px-4 py-3">Role</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Time In</th><th class="px-4 py-3">Time Out</th></tr></thead><tbody><tr v-if="!staff.length"><td colspan="5" class="p-10 text-center">No staff records today.</td></tr><tr v-for="r in staff" :key="r.user_id||r.id"><td class="px-4 py-3"><b>{{r.full_name||r.username}}</b><small class="block text-[var(--nx-text-muted)]">{{r.email}}</small></td><td class="px-4 py-3">{{r.role}}</td><td class="px-4 py-3"><NxBadge :tone="tone(r.status)">{{label(r.status)}}</NxBadge></td><td class="px-4 py-3">{{fmt(r.time_in_at)}}</td><td class="px-4 py-3">{{fmt(r.time_out_at)}}</td></tr></tbody></NxTableShell></NxCard><NxCard v-else title="My Activity Today" description="Your attendance and duty-status changes"><div class="max-h-[32rem] space-y-3 overflow-auto"><div v-for="r in myLogs" :key="r.id" class="rounded-md bg-[var(--nx-surface-muted)] p-3"><div class="flex justify-between gap-2"><NxBadge :tone="tone(r.new_status)">{{label(r.action)}}</NxBadge><small>{{fmt(r.created_at)}}</small></div><p class="mt-2 text-sm">{{label(r.old_status)}} → {{label(r.new_status)}}</p></div><p v-if="!myLogs.length" class="py-8 text-center">No activity today.</p></div></NxCard></div>
<div v-if="canViewTeam" class="grid gap-4 xl:grid-cols-2"><NxCard title="My Activity Today" description="Your attendance and duty-status changes"><div class="max-h-96 space-y-3 overflow-auto"><div v-for="r in myLogs" :key="r.id" class="rounded-md bg-[var(--nx-surface-muted)] p-3"><div class="flex justify-between"><b>{{label(r.action)}}</b><small>{{fmt(r.created_at)}}</small></div><p class="mt-1 text-sm text-[var(--nx-text-muted)]">{{label(r.old_status)}} → {{label(r.new_status)}}</p></div><p v-if="!myLogs.length" class="py-8 text-center">No activity today.</p></div></NxCard><NxCard title="Today’s Activity Log" description="Audit trail of staff attendance movement"><div class="max-h-96 space-y-3 overflow-auto"><div v-for="r in logs" :key="r.id" class="rounded-md bg-[var(--nx-surface-muted)] p-3"><div class="flex justify-between gap-2"><b>{{r.full_name||r.username}} · {{label(r.action)}}</b><small>{{fmt(r.created_at)}}</small></div><p class="mt-1 text-sm text-[var(--nx-text-muted)]">{{label(r.old_status)}} → {{label(r.new_status)}}</p></div><p v-if="!logs.length" class="py-8 text-center">No activity today.</p></div></NxCard></div>
<NxCard v-if="canViewTeam"><div class="flex flex-col gap-3 border-b border-[var(--nx-border)] p-5 md:flex-row md:items-end md:justify-between"><div><h2 class="font-bold">Attendance History</h2><p class="text-sm text-[var(--nx-text-muted)]">Historical time records and computed duty duration</p></div><div class="flex flex-wrap items-end gap-2"><label class="grid gap-1 text-xs font-semibold">From<input v-model="from" type="date" :class="inputClass"></label><label class="grid gap-1 text-xs font-semibold">To<input v-model="to" type="date" :class="inputClass"></label><NxButton :disabled="loading" @click="loadHistory">Apply</NxButton></div></div><NxTableShell min-width="950px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Staff</th><th class="px-4 py-3">Role</th><th class="px-4 py-3">Date</th><th class="px-4 py-3">Time In</th><th class="px-4 py-3">Time Out</th><th class="px-4 py-3">Duration</th><th class="px-4 py-3">Status</th></tr></thead><tbody><tr v-if="!history.length"><td colspan="7" class="p-10 text-center">No attendance records in this period.</td></tr><tr v-for="r in history" :key="r.id"><td class="px-4 py-3"><b>{{r.full_name||r.username}}</b><small class="block text-[var(--nx-text-muted)]">{{r.email}}</small></td><td class="px-4 py-3">{{r.role}}</td><td class="px-4 py-3">{{r.attendance_date}}</td><td class="px-4 py-3">{{fmt(r.time_in_at)}}</td><td class="px-4 py-3">{{fmt(r.time_out_at)}}</td><td class="px-4 py-3">{{duration(r.duty_minutes)}}</td><td class="px-4 py-3"><NxBadge :tone="tone(r.time_out_at?'OFFLINE':r.status)">{{label(r.time_out_at?'OFFLINE':r.status)}}</NxBadge></td></tr></tbody></NxTableShell></NxCard></div></template>
<style scoped>:global([data-nx-next-root="attendance"]){max-width:100%;overflow-x:hidden}</style>
